// === LWB图片伪装 (智绘姬原生接管 - 精确定位持久化版) ===
// 作用: 挂载到小白X插画卡片 (.xb-nd-img) 左上角
// 仅保留微型半透明图标按钮，点击将卡片认领为智绘姬识别格式
// 确保在数据层也精准插入在 [image: slot_id] 紧下方，重开聊天位置丝毫不乱

$(errorCatched(() => {
    const TAG = 'LWB图片伪装';
    const LOG = `[${TAG}]`;
    const log = (...a) => console.log(LOG, ...a);
    const error = (...a) => console.error(LOG, ...a);

    const PARENT = window.parent || window;
    const DOC = PARENT.document;

    // 1. 注入纯微型图标的半透明样式
    function injectStyles() {
        const STYLE_ID = 'th-lwb-fake-style';
        let style = DOC.getElementById(STYLE_ID);
        if (!style) {
            style = DOC.createElement('style');
            style.id = STYLE_ID;
            DOC.head.appendChild(style);
        }
        style.textContent = `
            .th-lwb-fake-btn {
                position: absolute;
                top: 6px;
                left: 6px;
                z-index: 15;
                width: 22px;
                height: 22px;
                padding: 0;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                background: rgba(0, 0, 0, 0.42);
                backdrop-filter: blur(4px);
                -webkit-backdrop-filter: blur(4px);
                border: 1px solid rgba(255, 255, 255, 0.18);
                color: rgba(255, 255, 255, 0.75);
                font-size: 11px;
                line-height: 1;
                border-radius: 4px;
                cursor: pointer;
                transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
                box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
                user-select: none;
                opacity: 0.35;
            }
            .xb-nd-img:hover .th-lwb-fake-btn {
                opacity: 0.75;
            }
            .th-lwb-fake-btn:hover {
                opacity: 0.98 !important;
                background: rgba(16, 185, 129, 0.85);
                color: #fff;
                border-color: rgba(255, 255, 255, 0.4);
                transform: scale(1.08);
            }
            .th-lwb-fake-btn.success {
                background: rgba(59, 130, 246, 0.75);
                color: #fff;
                opacity: 0.65;
            }
        `;
    }

    // 2. 从 LWB 原生 IndexedDB 读取图片记录
    async function getLwbIndexedDBPreview(imgId) {
        if (!imgId) return null;
        return new Promise((resolve) => {
            try {
                const req = indexedDB.open('xb_novel_draw_previews');
                req.onsuccess = (e) => {
                    const db = e.target.result;
                    if (!db.objectStoreNames.contains('previews')) return resolve(null);
                    const tx = db.transaction('previews', 'readonly');
                    const getReq = tx.objectStore('previews').get(imgId);
                    getReq.onsuccess = () => resolve(getReq.result || null);
                    getReq.onerror = () => resolve(null);
                };
                req.onerror = () => resolve(null);
            } catch (_) {
                resolve(null);
            }
        });
    }

    // 3. 智能多级寻图算法（IndexedDB -> 消息extra -> DOM -> 动态探测）
    async function resolveImageSrc(card, imgId) {
        // [级别 1] 优先读取本地 IndexedDB
        try {
            const preview = await getLwbIndexedDBPreview(imgId);
            if (preview?.savedUrl) return preview.savedUrl;
            if (preview?.base64) {
                return preview.base64.startsWith('data:') 
                    ? preview.base64 
                    : `data:image/png;base64,${preview.base64}`;
            }
        } catch (_) {}

        // [级别 2] 跨设备核心：从消息 extra.xiaobaixDrawSaved 提取
        const mesEl = card.closest ? card.closest('.mes') : null;
        const mesidStr = card.dataset.mesid ?? mesEl?.getAttribute('mesid');
        const mesid = mesidStr !== undefined && mesidStr !== null ? parseInt(mesidStr, 10) : -1;
        const context = (PARENT.SillyTavern || window.SillyTavern)?.getContext?.() || SillyTavern.getContext();
        const msg = (mesid >= 0 && context?.chat) ? context.chat[mesid] : null;

        if (msg?.extra) {
            const slotId = card.dataset.slotId || card.getAttribute('data-slot-id');
            const savedMap = msg.extra.xiaobaixDrawSaved || msg.extra.novelDrawSaved;
            if (savedMap) {
                if (slotId && savedMap[slotId]?.savedUrl) {
                    return savedMap[slotId].savedUrl;
                }
                for (const key of Object.keys(savedMap)) {
                    if (savedMap[key]?.imgId === imgId && savedMap[key]?.savedUrl) {
                        return savedMap[key].savedUrl;
                    }
                }
            }
        }

        // [级别 3] 从当前已渲染的 <img> 节点读取
        const imgEl = card.querySelector('img');
        const currentSrc = imgEl ? (imgEl.currentSrc || imgEl.src || '') : '';
        if (currentSrc && (currentSrc.includes('/user/images/') || currentSrc.startsWith('http') || currentSrc.startsWith('data:'))) {
            return currentSrc;
        }

        // [级别 4] 自动探测 /user/images/ 路径
        let filename = '';
        try {
            filename = new URL(currentSrc, window.location.origin).pathname.split('/').pop();
        } catch (_) {
            filename = currentSrc.split('/').pop()?.split('?')[0];
        }
        if (!filename && imgId) {
            filename = `comfy_${imgId}.png`;
        }

        if (filename) {
            const charName = context?.characters?.[context?.characterId]?.name || msg?.name || '';
            const candidates = [
                charName ? `/user/images/${charName}/${filename}` : null,
                `/user/images/${filename}`,
            ].filter(Boolean);

            for (const p of candidates) {
                try {
                    const res = await fetch(p, { method: 'HEAD' });
                    if (res.ok) return p;
                } catch (_) {}
            }
            if (candidates.length > 0) return candidates[0];
        }

        return currentSrc;
    }

    // 4. 将标记文本精准插入在 [image: slotId] 紧下方的辅助函数
    function insertMarkerAfterSlot(sourceText, slotId, markerText) {
        if (slotId) {
            const escapedSlotId = slotId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            // 匹配 [image: slot_id] 或 [img: slot_id]
            const slotRegex = new RegExp(`(\\[(?:image|img|图片)\\s*:\\s*${escapedSlotId}[^\\]]*\\])`, 'i');
            const match = slotRegex.exec(sourceText);
            if (match) {
                const insertPos = match.index + match[0].length;
                return sourceText.slice(0, insertPos) + `\n\n${markerText}\n` + sourceText.slice(insertPos);
            }
        }
        // 兜底回退到正文末尾
        return sourceText.trimEnd() + `\n\n${markerText}`;
    }

    // 5. 点击按钮执行认领并持久化
    async function handleClaimImage(card, btn) {
        try {
            const slotId = (card.dataset.slotId || card.getAttribute('data-slot-id') || '').trim();
            const imgId = (card.dataset.imgId || card.getAttribute('data-img-id') || '').trim();
            if (!imgId) {
                toastr?.warning('未能获取到此卡片的 LWB 图片编号', '⚠️ 提示');
                return;
            }
            const tag = imgId;

            // 检索真实图片地址
            const finalPath = await resolveImageSrc(card, imgId);
            if (!finalPath) {
                throw new Error('无法解析到此图片的有效访问路径');
            }

            // 计算 MD5 并写入智绘姬的 jiuguanStorage
            const cryptoLib = window.CryptoJS || PARENT.CryptoJS;
            if (!cryptoLib || !cryptoLib.MD5) {
                throw new Error('未检测到 CryptoJS，无法计算 MD5');
            }
            const md5 = cryptoLib.MD5(tag).toString();

            const context = (PARENT.SillyTavern || window.SillyTavern)?.getContext?.() || SillyTavern.getContext();
            const extensionSettings = context.extensionSettings || PARENT.extension_settings;
            if (!extensionSettings || !extensionSettings['st-chatu8']) {
                throw new Error('未检测到智绘姬(st-chatu8)插件');
            }

            const chatu8Settings = extensionSettings['st-chatu8'];
            if (!chatu8Settings.jiuguanStorage) {
                chatu8Settings.jiuguanStorage = {};
            }

            const uuid = (crypto.randomUUID && crypto.randomUUID()) || String(Date.now());
            chatu8Settings.jiuguanStorage[md5] = {
                images: [{
                    uuid: uuid,
                    path: finalPath,
                    thumbnail_path: finalPath,
                    date: Date.now(),
                    isVideo: false,
                    format: 'png',
                    source: 'server',
                }],
                index: 0,
                change: '',
                video: '',
                activeMode: 'image',
            };

            // 立即保存智绘姬的配置
            if (typeof context.saveSettingsDebounced === 'function') {
                context.saveSettingsDebounced();
            }

            // 定位消息楼层
            const mesEl = card.closest ? card.closest('.mes') : null;
            const mesidStr = card.dataset.mesid ?? mesEl?.getAttribute('mesid');
            const mesid = mesidStr !== undefined && mesidStr !== null ? parseInt(mesidStr, 10) : -1;

            const markerText = `<image>image### ${tag} ###</image>`;

            // 多层同步并精准插入到 [image: slotId] 紧下方
            if (mesid >= 0 && Array.isArray(context.chat) && context.chat[mesid]) {
                const targetMsg = context.chat[mesid];
                if (!targetMsg.mes.includes(tag)) {
                    // 1. 精确插在 slotId 占位符后，确保重开位置不漂移
                    targetMsg.mes = insertMarkerAfterSlot(targetMsg.mes, slotId, markerText);

                    // 2. 强行同步到当前分支的 swipes 数组
                    if (Array.isArray(targetMsg.swipes) && typeof targetMsg.swipe_id === 'number') {
                        targetMsg.swipes[targetMsg.swipe_id] = targetMsg.mes;
                    }

                    // 3. 标记脏数据状态
                    if (context.chatMetadata) {
                        context.chatMetadata.tainted = true;
                    }

                    // 4. 调用原生保存接口
                    if (typeof context.saveChat === 'function') {
                        await context.saveChat();
                    } else if (typeof PARENT.saveChatDebounced === 'function') {
                        PARENT.saveChatDebounced();
                    } else if (typeof PARENT.saveChat === 'function') {
                        await PARENT.saveChat();
                    }
                    log(`已成功将标记精准插入到第 ${mesid} 楼 slotId=${slotId} 紧下方并持久化保存`);
                }
            }

            // 5. 在当前 DOM 卡片下方即时插入占位容器，触发智绘姬当场挂载
            let container = card.nextElementSibling;
            if (!container || !container.classList.contains('chatu8-mounted-hook')) {
                container = DOC.createElement('div');
                container.className = 'chatu8-mounted-hook';
                container.style.marginTop = '8px';
                container.innerHTML = markerText;
                card.parentNode.insertBefore(container, card.nextSibling);
            }

            // 6. 核心优化：唤醒智绘姬即时渲染，杜绝显示为纯文本
            const mesTextEl = mesEl?.querySelector?.('.mes_text') || (card.closest ? card.closest('.mes_text') : null);
            if (mesTextEl && mesTextEl.dataset) {
                // 清理智绘姬的已处理缓存标记，让其重新扫描本楼层
                delete mesTextEl.dataset.chatu8Processed;
                delete mesTextEl.dataset.chatu8ContentLength;
                if (mesTextEl.attributes) {
                    Array.from(mesTextEl.attributes).forEach(attr => {
                        if (attr.name && attr.name.startsWith('data-tag-inserted-')) {
                            mesTextEl.removeAttribute(attr.name);
                        }
                    });
                }
            }

            // 广播事件通知智绘姬执行 processMesTextElements
            const evtSource = context?.eventSource || PARENT.eventSource || window.eventSource;
            const evtTypes = context?.eventTypes || PARENT.event_types || window.event_types;
            if (evtSource) {
                if (evtTypes?.MESSAGE_SWIPED) {
                    evtSource.emit(evtTypes.MESSAGE_SWIPED, mesid);
                }
                evtSource.emit('js_generation_ended');
            }
            if (typeof PARENT.processAllImagePlaceholders === 'function') {
                try { PARENT.processAllImagePlaceholders(); } catch (_) {}
            }

            // 7. 双重保障：若智绘姬因不在最新楼层/视口判断未即时响应，启动即时无缝预览兜底，绝不露出裸代码
            setTimeout(() => {
                if (container && container.isConnected) {
                    const hasChButton = container.querySelector('.image-tag-button, .st-chatu8-image-span');
                    if (!hasChButton && container.textContent.includes('image###')) {
                        log('智绘姬未在 250ms 内响应替换，启动即时无缝预览兜底');
                        container.innerHTML = `
                            <div class="st-chatu8-direct-preview" style="position: relative; display: inline-block; margin-top: 4px;">
                                <img src="${finalPath}" alt="认领预览" style="max-width: 100%; border-radius: 6px; box-shadow: 0 2px 8px rgba(0,0,0,0.25); display: block;" />
                                <div style="font-size: 11px; color: rgba(255,255,255,0.7); background: rgba(0,0,0,0.5); padding: 2px 6px; border-radius: 4px; position: absolute; bottom: 6px; left: 6px; pointer-events: none;">✨ 智绘姬已接管 (重开呈现原生控制条)</div>
                            </div>
                        `;
                    }
                }
            }, 250);

            btn.classList.add('success');
            btn.innerHTML = '<span>✓</span>';
            toastr?.success(`已认领并精准定位在原图紧下方！`, '✨ 认领成功');

        } catch (err) {
            error('认领出错:', err);
            toastr?.error(`认领失败: ${err.message || err}`, '❌ 错误');
        }
    }

    // 6. 挂载单张卡片
    function mountCard(card) {
        if (!card || card.dataset.thFakeMounted === 'true') return;
        card.dataset.thFakeMounted = 'true';

        // 清理旧可能残留的徽标
        card.querySelectorAll('.th-lwb-fake-btn, .th-lwb-video-badge').forEach(el => el.remove());

        const wrap = card.querySelector('.xb-nd-img-wrap') || card;
        const btn = DOC.createElement('button');
        btn.type = 'button';
        btn.className = 'th-lwb-fake-btn';
        btn.title = '✨ 认领为智绘姬图片（启用原生图生视频/修图）';
        btn.innerHTML = '<span>✨</span>';
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            e.preventDefault();
            handleClaimImage(card, btn);
        });
        wrap.appendChild(btn);
    }

    // 7. 扫描与监听
    function scanAndMountAll() {
        const cards = DOC.querySelectorAll('.xb-nd-img:not([data-th-fake-mounted="true"])');
        cards.forEach(mountCard);
    }

    injectStyles();
    scanAndMountAll();

    const chatContainer = DOC.querySelector('#chat') || DOC.body;
    if (chatContainer) {
        const observer = new MutationObserver(() => scanAndMountAll());
        observer.observe(chatContainer, { childList: true, subtree: true });
    }

    log('LWB图片伪装助手(精确定位版)已就绪');
}));
